class Solution {
    int gcd(int a, int b) {
        while (b) { int r = a % b; a = b; b = r; }
        return a;
    }
public:
    int mirrorReflection(int p, int q) {
        int g = gcd(p, q);
        p /= g; q /= g;
        if (p % 2 == 0) return 2;
        return q % 2 == 0 ? 0 : 1;
    }
};
